use std::collections::VecDeque;

const WALL_STYLE: u8 = 11;
const DOOR_STYLE: u8 = 15;

#[derive(Clone, Copy, Debug)]
pub(super) struct WorkbookMapDesign {
    pub(super) name: &'static str,
    pub(super) width: usize,
    pub(super) height: usize,
    pub(super) spawn: [i32; 2],
    encoded_styles: &'static str,
}

#[derive(Clone, Debug)]
pub(super) struct DecodedWorkbookMap {
    pub(super) styles: Vec<u8>,
    pub(super) enclosed: Vec<bool>,
    pub(super) exterior: Vec<bool>,
}

impl WorkbookMapDesign {
    pub(super) fn decode(self) -> DecodedWorkbookMap {
        let bytes = decode_base64(self.encoded_styles);
        let mut styles = vec![0; self.width * self.height];
        let mut cursor = 0;
        let mut position = 0;
        while cursor < bytes.len() {
            position += read_varint(&bytes, &mut cursor);
            let length = read_varint(&bytes, &mut cursor);
            let style = bytes[cursor];
            cursor += 1;
            let end = position + length;
            assert!(
                end <= styles.len(),
                "{} workbook map data exceeds its declared bounds",
                self.name
            );
            styles[position..end].fill(style);
            position = end;
        }

        let mut exterior = vec![false; styles.len()];
        let mut queue = VecDeque::new();
        for x in 0..self.width {
            enqueue_exterior(x, &styles, &mut exterior, &mut queue);
            enqueue_exterior(
                (self.height - 1) * self.width + x,
                &styles,
                &mut exterior,
                &mut queue,
            );
        }
        for z in 0..self.height {
            enqueue_exterior(
                z * self.width,
                &styles,
                &mut exterior,
                &mut queue,
            );
            enqueue_exterior(
                z * self.width + self.width - 1,
                &styles,
                &mut exterior,
                &mut queue,
            );
        }
        while let Some(index) = queue.pop_front() {
            let x = index % self.width;
            let z = index / self.width;
            if x > 0 {
                enqueue_exterior(
                    index - 1,
                    &styles,
                    &mut exterior,
                    &mut queue,
                );
            }
            if x + 1 < self.width {
                enqueue_exterior(
                    index + 1,
                    &styles,
                    &mut exterior,
                    &mut queue,
                );
            }
            if z > 0 {
                enqueue_exterior(
                    index - self.width,
                    &styles,
                    &mut exterior,
                    &mut queue,
                );
            }
            if z + 1 < self.height {
                enqueue_exterior(
                    index + self.width,
                    &styles,
                    &mut exterior,
                    &mut queue,
                );
            }
        }
        let enclosed = styles
            .iter()
            .zip(&exterior)
            .map(|(style, exterior)| !*exterior && !blocks_exterior_flood(*style))
            .collect();
        DecodedWorkbookMap {
            styles,
            enclosed,
            exterior,
        }
    }

    pub(super) fn centered_offset(self, index: usize) -> [i32; 2] {
        let x = index % self.width;
        let z = index / self.width;
        [
            x as i32 - (self.width as i32 - 1) / 2,
            z as i32 - (self.height as i32 - 1) / 2,
        ]
    }
}

fn blocks_exterior_flood(style: u8) -> bool { matches!(style, WALL_STYLE | DOOR_STYLE) }

fn enqueue_exterior(
    index: usize,
    styles: &[u8],
    exterior: &mut [bool],
    queue: &mut VecDeque<usize>,
) {
    if !exterior[index] && !blocks_exterior_flood(styles[index]) {
        exterior[index] = true;
        queue.push_back(index);
    }
}

fn decode_base64(encoded: &str) -> Vec<u8> {
    let mut bytes = Vec::with_capacity(encoded.len() * 3 / 4);
    let mut accumulator = 0_u32;
    let mut bit_count = 0_u32;
    for byte in encoded.bytes() {
        let value = match byte {
            b'A'..=b'Z' => byte - b'A',
            b'a'..=b'z' => byte - b'a' + 26,
            b'0'..=b'9' => byte - b'0' + 52,
            b'+' => 62,
            b'/' => 63,
            b'=' => break,
            _ => continue,
        };
        accumulator = (accumulator << 6) | u32::from(value);
        bit_count += 6;
        if bit_count >= 8 {
            bit_count -= 8;
            bytes.push((accumulator >> bit_count) as u8);
            accumulator &= (1_u32 << bit_count).wrapping_sub(1);
        }
    }
    bytes
}

fn read_varint(bytes: &[u8], cursor: &mut usize) -> usize {
    let mut value = 0_usize;
    let mut shift = 0;
    loop {
        let byte = bytes[*cursor];
        *cursor += 1;
        value |= usize::from(byte & 0x7f) << shift;
        if byte & 0x80 == 0 {
            return value;
        }
        shift += 7;
        assert!(
            shift < usize::BITS,
            "invalid workbook map varint"
        );
    }
}

