#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn workbook_maps_decode_to_their_exact_sheet_dimensions() {
        for design in [ARROGANCE, NIFFY, KYO, ARBITRATOR, ABANDONED, XY_PLANET] {
            assert_eq!(
                design.decode().styles.len(),
                design.width * design.height,
                "{}",
                design.name
            );
        }
    }

    #[test]
    fn workbook_maps_preserve_walls_doors_and_enclosed_floorplans() {
        for (design, expected_walls, expected_doors, expected_enclosed) in [
            (ARROGANCE, 1_033, 42, 5_275),
            (NIFFY, 716, 32, 3_288),
            (KYO, 334, 15, 1_394),
            (ARBITRATOR, 568, 24, 2_110),
            (ABANDONED, 295, 3, 623),
            (XY_PLANET, 139, 9, 353),
        ] {
            let decoded = design.decode();
            assert_eq!(
                decoded
                    .styles
                    .iter()
                    .filter(|style| **style == WALL_STYLE)
                    .count(),
                expected_walls,
                "{} walls",
                design.name
            );
            assert_eq!(
                decoded
                    .styles
                    .iter()
                    .filter(|style| **style == DOOR_STYLE)
                    .count(),
                expected_doors,
                "{} doors",
                design.name
            );
            assert_eq!(
                decoded
                    .enclosed
                    .iter()
                    .filter(|enclosed| **enclosed)
                    .count(),
                expected_enclosed,
                "{} enclosed cells",
                design.name
            );
        }
    }
}
